export function canonicalURL(value){try{const u=new URL(value.trim());if(!['http:','https:'].includes(u.protocol)||u.username||u.password)return null;const skip=new Set(['fbclid','gclid','dclid','msclkid','ttclid','_gl','mc_cid','mc_eid']);const q=[...u.searchParams].filter(([k])=>!k.toLowerCase().startsWith('utm_')&&!skip.has(k.toLowerCase())).sort(([a,b],[c,d])=>a<c?-1:a>c?1:b<d?-1:b>d?1:0);u.search=new URLSearchParams(q).toString();u.pathname=u.pathname.replace(/\/+$/,'')||'/';return u.href;}catch{return null;}}
export function matchLanding(a,r){const fields={campaign:'campaign_name',adset:'adset_name',ad:'name'};const one=s=>{const v=String(r['value'+s]||'').trim().toLowerCase(),n=String(a[fields[r['field'+s]]]||'').toLowerCase();if(!v||!fields[r['field'+s]])return false;return r['op'+s]==='equals'?n===v:r['op'+s]==='not_equals'?n!==v:r['op'+s]==='not_contains'?!n.includes(v):r['op'+s]==='contains'&&n.includes(v);};return one('')&&(!r.second||one('2'));}
export const expectedURLs=r=>[...new Set(String(r.url||'').split('\n').filter(v=>v.trim()).map(canonicalURL))];
export function landingChecks(ads,rules){return ads.map(a=>{const matched=rules.filter(r=>matchLanding(a,r)),actual=[...new Set((a.landing_urls||[]).map(canonicalURL))];let status='MISSING_RULE',allowed=[];if(matched.length){if(matched.some(r=>!r.confirmed))status='UNCONFIRMED_RULE';else{const sets=matched.map(expectedURLs);if(sets.some(s=>!s.length||s.includes(null)))status='INVALID_RULE';else if(new Set(sets.map(s=>JSON.stringify(s.slice().sort()))).size>1)status='RULE_CONFLICT';else{allowed=sets[0];status=!actual.length||actual.includes(null)?'UNREADABLE':actual.every(u=>allowed.includes(u))?'MATCH':'URL_MISMATCH';}}}return {ad_id:a.id,status,actual_urls:actual.filter(Boolean).sort(),allowed_urls:allowed.slice().sort()};});}
